	if client.requestCount() != 3 {
		t.Fatalf("expected 3 token requests, got %d", client.requestCount())
	}
	if got := client.requests[2].url; got != "https://auth.example.com/token" {
		t.Errorf("expected the fall-back at the token URL, got %q", got)
	}
	if got := client.requests[2].body; !strings.HasPrefix(got, "grant_type=password&") {
		t.Errorf("expected the fall-back to be the password grant, got %q", got)
	}
	if headers["Authorization"] != "Bearer tok3" {
		t.Errorf("expected the fall-back token, got %q", headers["Authorization"])
	}
